//! EEVEE 5.2.2's GGX glass and LTC lookup tables, read from `eevee_transmission_tables.f32le`.
//!
//! The asset is generated by `scripts/extract_eevee_transmission_tables.py` from `eevee_lut.cc` at Blender v5.2.2. It
//! holds little-endian f32 values in this order, with EEVEE's own index order:
//! - `brdf[y][x][channel]` (64 × 64 × 2, scale and bias): `x` is the roughness, `y` is `sqrt(1 - cos θ)`;
//! - `btdf[layer][y][x]` (16 × 64 × 64): the transmission factor for an IOR above one, `x` is `sqrt(f0)`;
//! - `bsdf[layer][y][x][channel]` (16 × 64 × 64 × 3, scale, bias and transmission factor): for an IOR below one,
//!   `x` is `ior²` and `y` is the critical-angle-remapped cosine;
//! - `ltc_mat[y][x][channel]` (64 × 64 × 4): the inverse LTC matrix of the GGX lobe, `(m11, m13, m31, m33)`, with `x`
//!   the roughness and `y` `sqrt(1 - cos θ)`;
//! - `disk[y][x]` (64 × 64): the clipped sphere diffuse integral of a disk light, `x` is `avg_dir_z · 0.5 + 0.5` and `y`
//!   the form factor.
//!
//! Every table is 64 texels across, with texel `i` at coordinate `i / 63`, and the layers hold roughness `layer / 16`.

use std::sync::LazyLock;

const TABLE_SIZE: usize = 64;
const LAYER_COUNT: usize = 16;
const BRDF_LEN: usize = TABLE_SIZE * TABLE_SIZE * 2;
const BTDF_LEN: usize = LAYER_COUNT * TABLE_SIZE * TABLE_SIZE;
const BSDF_LEN: usize = LAYER_COUNT * TABLE_SIZE * TABLE_SIZE * 3;
const LTC_LEN: usize = TABLE_SIZE * TABLE_SIZE * 4;
const DISK_LEN: usize = TABLE_SIZE * TABLE_SIZE;
const BTDF_OFFSET: usize = BRDF_LEN;
const BSDF_OFFSET: usize = BTDF_OFFSET + BTDF_LEN;
const LTC_OFFSET: usize = BSDF_OFFSET + BSDF_LEN;
const DISK_OFFSET: usize = LTC_OFFSET + LTC_LEN;

static ASSET: &[u8] = include_bytes!("eevee_transmission_tables.f32le");

/// The decoded values, decoded once. A wrong asset length panics on first use, which the unit test catches.
static VALUES: LazyLock<Vec<f32>> = LazyLock::new(|| {
    let values: Vec<f32> = ASSET
        .as_chunks::<4>()
        .0
        .iter()
        .map(|bytes| f32::from_le_bytes(*bytes))
        .collect();
    assert_eq!(
        values.len(),
        DISK_OFFSET + DISK_LEN,
        "eevee_transmission_tables.f32le has the wrong length"
    );
    values
});

fn values() -> &'static [f32] {
    &VALUES
}

/// The split-sum scale (`channel` 0) or bias (`channel` 1) at texel `(x, y)` of the GGX BRDF table.
pub(super) fn brdf(x: usize, y: usize, channel: usize) -> f64 {
    f64::from(values()[(y * TABLE_SIZE + x) * 2 + channel])
}

/// The transmission factor at texel `(x, y)` of roughness layer `layer` of the IOR-above-one table.
pub(super) fn btdf(layer: usize, x: usize, y: usize) -> f64 {
    f64::from(values()[BTDF_OFFSET + (layer * TABLE_SIZE + y) * TABLE_SIZE + x])
}

/// Channel `channel` (0 scale, 1 bias, 2 transmission factor) at texel `(x, y)` of roughness layer `layer` of the
/// IOR-below-one table.
pub(super) fn bsdf(layer: usize, x: usize, y: usize, channel: usize) -> f64 {
    f64::from(values()[BSDF_OFFSET + ((layer * TABLE_SIZE + y) * TABLE_SIZE + x) * 3 + channel])
}

/// Entry `channel` (0 to 3, `m11`, `m13`, `m31`, `m33`) of the inverse LTC matrix at texel `(x, y)`.
pub(super) fn ltc_matrix(x: usize, y: usize, channel: usize) -> f64 {
    f64::from(values()[LTC_OFFSET + (y * TABLE_SIZE + x) * 4 + channel])
}

/// The clipped sphere diffuse integral at texel `(x, y)`: `x` is `avg_dir_z · 0.5 + 0.5`, `y` the form factor.
pub(super) fn disk_integral(x: usize, y: usize) -> f64 {
    f64::from(values()[DISK_OFFSET + y * TABLE_SIZE + x])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn asset_has_eevee_first_texels() -> Result<(), String> {
        // `brdf_ggx[0][0]` is {0.999996, 0, 0}; `bsdf_ggx[0][0][0]` is {0, 0.999996, 0}.
        if (brdf(0, 0, 0) - 0.999_996).abs() > 1.0e-6 || brdf(0, 0, 1).abs() > 1.0e-9 {
            return Err("the BRDF texel (0, 0) is not EEVEE's".to_owned());
        }
        if (bsdf(0, 0, 0, 1) - 0.999_996).abs() > 1.0e-6 || bsdf(0, 0, 0, 0).abs() > 1.0e-9 {
            return Err("the BSDF texel (0, 0, 0) is not EEVEE's".to_owned());
        }
        Ok(())
    }

    #[test]
    fn ltc_and_disk_tables_have_eevee_first_texels() -> Result<(), String> {
        // `ltc_mat_ggx[0][0]` is {1, 0, 0, 0.00002}; `ltc_disk_integral[0][0]` is 0 and the last texel is one.
        if (ltc_matrix(0, 0, 0) - 1.0).abs() > 1.0e-6
            || (ltc_matrix(0, 0, 3) - 2.0e-5).abs() > 1.0e-7
        {
            return Err("the LTC texel (0, 0) is not EEVEE's".to_owned());
        }
        if disk_integral(0, 0).abs() > 1.0e-9 || (disk_integral(63, 63) - 1.0).abs() > 1.0e-6 {
            return Err("the disk integral corners are not EEVEE's".to_owned());
        }
        Ok(())
    }
}
